"""Read immutable GT-only Stage2 masks generated by build_static_masks.py."""
import json
from pathlib import Path
import numpy as np
import torch
from .condition import sample_pyramid
from .dataset import input_xyz
from .storage import file_sha
from .voxelization import unpack_children

class StaticMaskCache:
 def __init__(self,root,dataset_root,geometry):
  self.root=Path(root);self.geometry=geometry
  state=json.loads((self.root/'status.json').read_text())
  if state.get('status')!='COMPLETE' or state.get('geometry_sha256')!=geometry.sha256 or state.get('source_manifest_sha256')!=file_sha(Path(dataset_root)/'manifest.json'):raise ValueError('Static cache incompatible or incomplete')
  self.manifest=state['source_manifest_sha256']
 def assemble(self,record,cfg,device,adapter):
  policy=cfg['candidates']
  if policy['mode']!='oracle' or policy.get('negative_fraction',0)!=0 or policy.get('oracle_score','neutral')!='neutral' or cfg['model'].get('child_bridge','none')!='none':raise ValueError('GT-only no-extra-parents neutral-score protocol only')
  path=self.root/'frames'/record['sequence']/f"{record['frame']:06d}.npz"
  with np.load(path,allow_pickle=False) as z:
   if str(z['manifest_sha'])!=self.manifest:raise ValueError('Stale cache manifest')
   ids=z['ids'];target_bits=z['target']
   if not np.array_equal(ids,record['parent_ids']) or not np.array_equal(target_bits,record['child_occ_mask']):raise ValueError('Cache parent or target mismatch')
   obs=unpack_children(z['observed'],self.geometry);valid=unpack_children(z['valid'],self.geometry);target=unpack_children(target_bits,self.geometry)
  if len(ids)>cfg['training']['max_parent_tokens']:raise RuntimeError('Full scene exceeds token limit')
  xyz=input_xyz(Path(cfg['data_root'])/record['sequence']/'input_'/f"{record['frame']:06d}.npy");x=torch.from_numpy(xyz).to(device)
  with torch.no_grad():pyramid=adapter.encode_features(x)
  parent=torch.as_tensor(ids.astype(np.int64),device=device);centers=self.geometry.centers(self.geometry.unflatten(parent)).float()
  c={'lidar_features':sample_pyramid(pyramid,centers,self.geometry.origin,self.geometry.maximum).detach().half(),'parent_score':torch.ones(len(ids),device=device),'observed_child':torch.as_tensor(obs,device=device),'valid_child_mask':torch.as_tensor(valid,device=device)}
  source={'mode':'oracle_not_deployable','nearby_negatives':0,'stage1_nfe':0,'stage1_encoder_forwards':1,'parent_score_source':'constant_neutral','static_mask_cache':True}
  return parent,c,torch.as_tensor(target,device=device),source
